List<String>? bilgiOf(String ad) {
  // büyük İ/I önce çevrilir (toLowerCase noktalı i'yi bozabilir); boşluk ve kesme işaretleri atılır ("Nûh'un Gemisi" -> "nûhungemisi")
  String norm(String x) => x.replaceAll('İ', 'i').replaceAll('I', 'ı').toLowerCase().replaceAll(RegExp("[ '’‘]"), '');
  final a = norm(ad);
  MapEntry<String, List<String>>? en;
  var enPuan = -1;
  for (final e in kBilgi.entries) {
    // "=anahtar": adın tamamı buna eşit olmalı ("dolu" "dolunay"ı çalmasın); öbürleri: adın içinde geçen en uzun anahtar kazanır
    final tam = e.key.startsWith('=');
    final k = norm(tam ? e.key.substring(1) : e.key); // anahtardaki boşluk da atılır ("bal arısı" -> "balarısı")
    if (tam ? a != k : !a.contains(k)) continue;
    final puan = tam ? 1000 : k.length;
    if (puan > enPuan) {
      en = e;
      enPuan = puan;
    }
  }
  return en?.value;
}

void bilgiGoster(BuildContext context, String ad, String ek) {
  final b = bilgiOf(ad);
  showModalBottomSheet(
    context: context,
    backgroundColor: R.surface,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(R.r28))),
    builder: (c) => SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 18, 20, 20),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(children: [
              const Icon(Icons.info_outline_rounded, color: R.gold, size: 22),
              const SizedBox(width: 10),
              Expanded(child: Text(ad, style: ts(R.text, 20, FontWeight.w700))),
              Bas(onTap: () => Navigator.pop(c), child: const Icon(Icons.close_rounded, color: R.sub)),
            ]),
            const SizedBox(height: 12),
            if (b == null)
              Text('Bu $ek için bilgi eklenecek.', style: ts(R.sub, 15, FontWeight.w400))
            else
              for (final s in b)
                Padding(
                  padding: const EdgeInsets.only(bottom: 10),
                  child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    const Padding(padding: EdgeInsets.only(top: 7, right: 10), child: Icon(Icons.circle, size: 6, color: R.primary)),
                    Expanded(child: Text(s, style: ts(R.text, 15, FontWeight.w400).copyWith(height: 1.45))),
                  ]),
                ),
          ],
        ),
      ),
    ),
  );
}
